import{_ as s,o as t,c as a,a2 as n}from"./chunks/framework.C-si7TFR.js";const p=JSON.parse('{"title":"Conversations and sessions","description":"","frontmatter":{"title":"Conversations and sessions"},"headers":[],"relativePath":"guide/agent-workspace.md","filePath":"guide/agent-workspace.md"}'),o={name:"guide/agent-workspace.md"};function r(i,e,l,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="conversations-and-sessions" tabindex="-1">Conversations and sessions <a class="header-anchor" href="#conversations-and-sessions" aria-label="Permalink to &quot;Conversations and sessions&quot;">​</a></h1><p>Use the agent workspace for open-ended tasks that require model reasoning and tools. Agents dynamically plan and adjust each next step from goals, context and tool results, and can invoke workflows as tools. Workflow mode follows predefined nodes, connections and branches for repeatable, controlled execution. Switching modes does not change existing data.</p><h2 id="start-a-conversation" tabindex="-1">Start a conversation <a class="header-anchor" href="#start-a-conversation" aria-label="Permalink to &quot;Start a conversation&quot;">​</a></h2><ol><li>Select an existing agent or follow <a href="./agents.html">Create an agent</a>.</li><li>Select <strong>Start conversation</strong>, then provide the goal, inputs and expected output.</li><li>Let the response finish, inspect tool cards and results, then send a follow-up.</li></ol><p>If no model is configured, the conversation page displays setup guidance. Complete it before expecting the agent to run.</p><h2 id="manage-sessions" tabindex="-1">Manage sessions <a class="header-anchor" href="#manage-sessions" aria-label="Permalink to &quot;Manage sessions&quot;">​</a></h2><p>The session list offers search, pin, archive and delete actions as available to the current role and interface.</p><ul><li>A <strong>session</strong> retains task context and can be continued from the agent or trace entry.</li><li><strong>Archive</strong> hides inactive sessions; it is not deletion.</li><li><strong>Delete</strong> affects local conversation records. Check that the context is no longer needed.</li><li><strong>Clearing or editing messages</strong> changes subsequent context. Check inputs and authorization before rerunning.</li></ul><h2 id="inspect-execution-traces" tabindex="-1">Inspect execution traces <a class="header-anchor" href="#inspect-execution-traces" aria-label="Permalink to &quot;Inspect execution traces&quot;">​</a></h2><p>Open a trace from its session to inspect tasks, subtasks, tool calls and related nodes. Scheduled tasks have separate run records, with access to the latest conversation from the task row.</p><p>Requests and responses may contain business data. Redact them before exporting or sharing. A log entry alone does not prove that an external operation succeeded; inspect the actual tool result.</p><h2 id="check-for-success" tabindex="-1">Check for success <a class="header-anchor" href="#check-for-success" aria-label="Permalink to &quot;Check for success&quot;">​</a></h2><ul><li>The response matches the requested goal, inputs and output.</li><li>Tool cards contain no unresolved authentication, network or permission errors.</li><li>Independently verify file changes, external calls and workflow results.</li><li>Add constraints for ambiguous tasks; model descriptions are not proof of execution.</li></ul><p>Next: <a href="./skills.html">Skills and MCP</a> · <a href="./schedules.html">Scheduled tasks</a></p>',14)])])}const g=s(o,[["render",r]]);export{p as __pageData,g as default};
